cat > gen_id.py <<'PYEOF'
"""Print the next order id.

Reads ids.txt from the current directory (one order id per line, most recent
last) and prints the next id in the sequence to stdout, followed by a newline.
Ids have the form ORD-<4 base36 chars>.
"""

from pathlib import Path

PREFIX = "ORD-"
WIDTH = 4
ALPHABET = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
RADIX = len(ALPHABET)  # 36


def to_base36(value: int) -> str:
    if value == 0:
        return "0"
    digits = []
    while value:
        value, rem = divmod(value, RADIX)
        digits.append(ALPHABET[rem])
    return "".join(reversed(digits))


def next_id(last: str) -> str:
    suffix = last.strip().upper()
    if not suffix.startswith(PREFIX):
        raise ValueError(f"unexpected id line: {last!r}")
    suffix = suffix[len(PREFIX):]
    value = int(suffix, RADIX)
    return PREFIX + to_base36(value + 1).zfill(WIDTH)


def main() -> None:
    lines = Path("ids.txt").read_text(encoding="utf-8").splitlines()
    for line in reversed(lines):
        if line.strip():
            print(next_id(line))
            return


if __name__ == "__main__":
    main()
PYEOF

