"""Read ids.txt and print the next order id (ORD- followed by 4 base36 chars)."""

import os

ALPHABET = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
BASE = len(ALPHABET)  # 36


def base36_encode(n: int, width: int = 4) -> str:
    """Encode an integer as a zero-padded base36 string of given width."""
    chars = []
    for _ in range(width):
        chars.append(ALPHABET[n % BASE])
        n //= BASE
    return "".join(reversed(chars))


def base36_decode(s: str) -> int:
    """Decode a base36 string to an integer."""
    n = 0
    for c in s:
        n = n * BASE + ALPHABET.index(c)
    return n


def main():
    ids_file = "ids.txt"
    last_id = None

    with open(ids_file, "r") as f:
        for line in f:
            line = line.strip()
            if line:
                last_id = line

    if last_id is None:
        # No ids yet, start from 0
        next_num = 0
    else:
        suffix = last_id[4:]  # Everything after "ORD-"
        last_num = base36_decode(suffix)
        next_num = last_num + 1

    next_suffix = base36_encode(next_num)
    print(f"ORD-{next_suffix}")


if __name__ == "__main__":
    main()

