#!/usr/bin/env python3
"""Copy the project/ directory to backups/project/, preserving layout and file contents."""

import shutil
from pathlib import Path

SRC = Path("project")
DST = Path("backups") / "project"


def main() -> None:
    if DST.exists():
        shutil.rmtree(DST)
    shutil.copytree(SRC, DST, symlinks=False, dirs_exist_ok=False)
    print(f"Backup created: {DST}")


if __name__ == "__main__":
    main()

