import os
import re

def list_reports():
    """Print file names under reports/, one per line, in report order."""
    reports_dir = "reports"
    files = [f for f in os.listdir(reports_dir) if f.startswith("report-") and f.endswith(".txt")]
    # Sort numerically by the number in the filename
    files.sort(key=lambda f: int(re.search(r'report-(\d+)\.txt', f).group(1)))
    for f in files:
        print(f)

if __name__ == "__main__":
    list_reports()

