#!/usr/bin/env python3
"""List report files under reports/ in report order (numeric, not lexicographic).

Directory listing order (os.listdir) is not guaranteed stable or sorted, and a
plain lexicographic sort would put report-10.txt before report-2.txt. Reports
are named report-<n>.txt with <n> counting up from 1, so order them by n.
"""

import os
import re
import sys

REPORTS_DIR = "reports"
_PATTERN = re.compile(r"^report-(\d+)\.txt$")


def _sort_key(name):
    m = _PATTERN.match(name)
    if m:
        return (0, int(m.group(1)))
    return (1, name)


def main():
    if not os.path.isdir(REPORTS_DIR):
        print(f"error: no such directory: {REPORTS_DIR}", file=sys.stderr)
        return 1
    entries = os.listdir(REPORTS_DIR)
    files = [e for e in entries if os.path.isfile(os.path.join(REPORTS_DIR, e))]
    for name in sorted(files, key=_sort_key):
        print(name)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
EOF

