args.content:
"""Rotate entries in app.log to archive.log.

Usage: python rotate.py AS_OF

Every line of app.log starts with a timestamp formatted YYYY-MM-DD HH:MM:SS
followed by a message. Entries strictly older than 7 days before AS_OF (a Unix
timestamp in integer seconds) are moved to archive.log (appending, preserving
order), and app.log is rewritten with the remaining entries.
"""

import sys
from datetime import datetime, timezone


def parse_timestamp(line: str) -> datetime | None:
    """Extract the leading timestamp from a log line."""
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(
            tzinfo=timezone.utc
        )
    except (ValueError, IndexError):
        return None


def main() -> None:
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print("AS_OF must be an integer Unix timestamp", file=sys.stderr)
        sys.exit(1)

    cutoff = as_of - 7 * 24 * 60 * 60  # 7 days in seconds
    cutoff_dt = datetime.fromtimestamp(cutoff, tz=timezone.utc)

    try:
        with open("app.log") as f:
            lines = f.readlines()
    except FileNotFoundError:
        print("app.log not found", file=sys.stderr)
        sys.exit(1)

    kept: list[str] = []
    archived: list[str] = []

    for line in lines:
        line_stripped = line.rstrip("\n")
        if not line_stripped:
            # preserve blank lines in kept
            kept.append(line)
            continue
        ts = parse_timestamp(line_stripped)
        if ts is None or ts < cutoff_dt:
            archived.append(line)
        else:
            kept.append(line)

    # Append to archive.log (preserving order)
    if archived:
        with open("archive.log", "a") as f:
            f.writelines(archived)

    # Rewrite app.log with remaining entries
    if kept:
        with open("app.log", "w") as f:
            f.writelines(kept)
    else:
        # If nothing kept, write empty file
        open("app.log", "w").close()


if __name__ == "__main__":
    main()

